dslRule:
new java.util.ArrayList($x) :: isNullable($x) && instanceof($x, "java.util.Collection")
=> new java.util.ArrayList($x != null ? $x : java.util.Collections.emptyList())
;;

beforeExample:
import java.util.ArrayList;
import java.util.List;
import java.util.Collection;

public class TestClass {
    List<String> maybeNullList;
    Collection<Integer> maybeNullCollection;

    public TestClass(List<String> list) {
        this.maybeNullList = list;
    }

    public void init() {
        List<String> filteredList = new ArrayList<>(maybeNullList);
        List<Integer> filteredCollection = new ArrayList<>(maybeNullCollection);
    }
}

afterExample:
import java.util.ArrayList;
import java.util.List;
import java.util.Collection;
import java.util.Collections;

public class TestClass {
    List<String> maybeNullList;
    Collection<Integer> maybeNullCollection;

    public TestClass(List<String> list) {
        this.maybeNullList = list;
    }

    public void init() {
        List<String> filteredList = new ArrayList<>(maybeNullList != null ? maybeNullList : java.util.Collections.emptyList());
        List<Integer> filteredCollection = new ArrayList<>(maybeNullCollection != null ? maybeNullCollection : java.util.Collections.emptyList());
    }
}

